{
  "schemaVersion": "3",
  "kind": "mixin",
  "name": "audit-mixin-cred",
  "displayName": "Audit mixin credential",
  "description": "Test mixin of the docker-sbx audit, declares an optional credential of a service sbx does not know, injected into a host that never resolves.",
  "sandbox": {
    "image": "sbx-kit-src:spec-588c26b42499"
  },
  "permissions": {
    "network": {
      "allow": [
        "api.audit.invalid:443"
      ]
    }
  },
  "credentials": [
    {
      "service": "audit-svc",
      "description": "Dummy credential of the audit",
      "apiKey": {
        "name": "",
        "inject": [
          {
            "domain": "api.audit.invalid",
            "header": "X-Audit-Key",
            "format": "%s"
          }
        ]
      }
    }
  ]
}

install.command:
env -i PATH="$PATH" HOME="$HOME" USER="$USER" TERM="$TERM" HTTP_PROXY="$HTTP_PROXY" HTTPS_PROXY="$HTTPS_PROXY" NO_PROXY="$NO_PROXY" http_proxy="$http_proxy" https_proxy="$https_proxy" no_proxy="$no_proxy" SSL_CERT_FILE="$SSL_CERT_FILE" SSL_CERT_DIR="$SSL_CERT_DIR" REQUESTS_CA_BUNDLE="$REQUESTS_CA_BUNDLE" CURL_CA_BUNDLE="$CURL_CA_BUNDLE" NODE_EXTRA_CA_CERTS="$NODE_EXTRA_CA_CERTS" MCP_GATEWAY_URL="$MCP_GATEWAY_URL" MCP_SENTINEL_TOKEN_NAME="$MCP_SENTINEL_TOKEN_NAME" sh -c '{
